func (q *Queries) ListRetrospectivesByWorkspace(ctx context.Context, arg ListRetrospectivesByWorkspaceParams) ([]Retrospective, error) {
	rows, err := q.db.Query(ctx, listRetrospectivesByWorkspace,
		arg.WorkspaceID,
		arg.Limit,
		arg.Offset,
		arg.Status,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []Retrospective{}
	for rows.Next() {
		var i Retrospective
		if err := rows.Scan(
			&i.ID,
			&i.WorkspaceID,
			&i.Status,
			&i.Scope,
			&i.ScopeID,
			&i.Trigger,
			&i.Since,
			&i.IssueID,
			&i.TaskID,
			&i.AutopilotID,
			&i.RequestedBy,
			&i.DismissedAt,
			&i.DismissedBy,
			&i.LessonCount,
			&i.FailureReason,
			&i.StartedAt,
			&i.CompletedAt,
			&i.CreatedAt,
			&i.UpdatedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

